-- 0031_far418_source_expansion.sql
--
-- CC-BOUNDSTONE-INGEST-1.1 §7 (FAR-418) — source expansion to NATIONAL
-- COMPLETENESS. GENERATED by scripts/far418-gen-source-expansion.mjs from
-- scripts/far418-rosters.mjs. Do not hand-edit; edit the roster and re-run.
--
-- ⚠️ UN-APPLIED. No production seed is authorized by this CC (§2).
--
-- WHY COMPLETENESS BEFORE TUNING (§7, §12): 26 of 51 commissions is not
-- "commissions covered", it is a map with holes that reads as quiet states.
-- Every class below is registered for all of its members in one go, and no
-- member is tuned until the class is whole.
--
-- NOTHING HERE ACTIVATES ANYTHING. Every row lands status='registered'.
-- Activation is `source-poller verify`'s job and happens only for a source
-- whose feed actually resolved. A URL we could not confirm therefore fails
-- loudly (status='error', reported by the §8 staleness monitor) instead of
-- sitting in the registry looking like coverage.
--
-- URL PROVENANCE: fetch_config.url_provenance='pattern' marks an endpoint
-- derived from the dominant naming convention and NOT yet probed. That is the
-- honest state of the 51 governor rows at authoring time. See
-- docs/far-418/source-expansion-report.md for the count and the follow-up.

begin;

create temporary table far418_states (abbr text primary key, name text, gov_host text) on commit drop;
insert into far418_states (abbr, name, gov_host) values
