create temporary table far418_markets (key text primary key, name text, domain text, notices_path text, queue_key text) on commit drop;
insert into far418_markets (key, name, domain, notices_path, queue_key) values
    ('caiso', 'California ISO', 'caiso.com', '/informed/Pages/Notifications/Default.aspx', null),
    ('ercot', 'Electric Reliability Council of Texas', 'ercot.com', '/services/comm/mkt_notices', 'iso:ercot-gis'),
    ('isone', 'ISO New England', 'iso-ne.com', '/participate/participant-readiness/', null),
